1555: # A TEST HOOK's milliseconds: "<ms>" for every run, or "<model>=<ms>[|<model>=<ms>...]" (with
1556: # "*=<ms>" for the other models) for the runs of $Model; 0 when unset or not for this model.
1557: function Get-TestHookMs {
1558:     param([string]$Value, [string]$Model)
1559:     if (-not $Value) { return 0 }
1560:     $pick = ''
1561:     foreach ($item in $Value.Split('|')) {
1562:         $eq = $item.IndexOf('=')
1563:         if ($eq -lt 0) { if ($item.Trim() -and -not $pick) { $pick = $item.Trim() }; continue }
1564:         $k = $item.Substring(0, $eq).Trim()
1565:         if ($k -ceq $Model) { $pick = $item.Substring($eq + 1).Trim(); break }
1566:         if ($k -eq '*') { $pick = $item.Substring($eq + 1).Trim() }
1567:     }
1568:     $ms = 0
1569:     if ([int]::TryParse($pick, [ref]$ms) -and $ms -gt 0) { return $ms }
1570:     return 0
1571: }
